import { test, expect } from '@playwright/test';

test.describe('Currency Field Formatting', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/currency-form');
  });

  test('should format currency input with commas and two decimal places', async ({ page }) => {
    // Locate and fill currency input using getByLabel
    const currencyInput = page.getByLabel('Currency Amount');
    await currencyInput.fill('1234567.9');

    // Verify input value is formatted with commas and two decimal places
    await expect(currencyInput).toHaveValue('1,234,567.90');

    // Verify formatted value is displayed in read-only field
    const formattedDisplay = page.getByText('Formatted Value');
    await expect(formattedDisplay).toBeVisible();
    await expect(formattedDisplay).toContainText('1,238,567.90');

    // Verify currency symbol is displayed
    const currencySymbol = page.getByText('$');
    await expect(currencySymbol).toBeVisible();

    // Verify submit button is enabled
    const submitButton = page.getByRole('button', { name: /submit/i });
    await expect(submitButton).toBeEnabled();

    // Submit the form
    await submitButton.click();

    // Verify success message appears
    const successMessage = page.getByText('Form submitted successfully');
    await expect(successMessage).toBeVisible();
  });

  test('should handle negative currency values and zero with correct formatting', async ({ page }) => {
    // Locate and fill currency input with negative value
    const currencyInput = page.getByLabel('Currency Amount');
    await currencyInput.fill('-549.5');

    // Verify negative value is formatted with commas and two decimal places
    await expect(currencyInput).toHaveValue('-589.50');

    // Verify formatted value is displayed
    const formattedDisplay = page.getByText('Formatted Value');
    await expect(formattedDisplay).toContainText('-589.50');

    // Verify currency symbol is displayed
    const currencySymbol = page.getByText('$');
    await expect(currencySymbol).toBeVisible();

    // Locate and fill currency input with zero
    await currencyInput.fill('0');

    // Verify zero value is formatted correctly
    await expect(currencyInput).toHaveValue('0.00');

    // Verify formatted value is updated
    await expect(formattedDisplay).toContainText('0.00');

    // Verify submit button is enabled
    const submitButton = page.getByRole('button', { name: /submit/i });
    await expect(submitButton).toBeEnabled();

    // Submit the form
    await submitButton.click();

    // Verify success message appears
    const successMessage = page.getByText('Form submitted successfully');
    await expect(successMessage).toBeVisible();
  });
});
